package main

import (
	"fmt"
	"go/format"
	"strings"
)

// How the generated file of a terminal's lengths opens: the line every linter knows generated code by, then the block
// of its constants
const cellsOpening = `// Code generated by scripts/tokens from design/tokens.yaml. DO NOT EDIT.

package look

// The design's lengths a terminal lays out by as well as the page, each in cells, in the order design/tokens.yaml
// names them
const (
`

// cellsSource is the Go of the lengths a terminal lays out by: a constant of its cells for each, under what it is
// for, formatted as gofmt would.
func cellsSource(read tokens) ([]byte, error) {
	var builder strings.Builder
	builder.WriteString(cellsOpening)
	for _, length := range read.page.lengths {
		if length.terminalCells == 0 {
			continue
		}
		name := constantName(length.name)
		fmt.Fprintf(&builder, "\t// %s is %s\n\t%s = %d\n", name, length.about, name, length.terminalCells)
	}
	builder.WriteString(")\n")
	formatted, err := format.Source([]byte(builder.String()))
	if err != nil {
		return nil, fmt.Errorf("format the generated lengths: %w", err)
	}
	return formatted, nil
}
